diff --git a/tests/Invoke-Mirror.Tests.ps1 b/tests/Invoke-Mirror.Tests.ps1
index 3333333..4444444 100644
--- a/tests/Invoke-Mirror.Tests.ps1
+++ b/tests/Invoke-Mirror.Tests.ps1
@@ -1,3 +1,11 @@
 Describe 'Invoke-Mirror exit classification' {
+    It 'uses the captured robocopy exit code after diagnostics' {
+        $source = Get-Content -Raw src/Invoke-Mirror.ps1
+        $source.IndexOf('$copyExit = $LASTEXITCODE') | Should -BeLessThan $source.IndexOf('where.exe powershell.exe')
+        $source | Should -Match 'if \(\$copyExit -le 7\)'
+    }
+    It 'keeps the documented robocopy success boundary' {
+        (3 -le 7) | Should -BeTrue
+        (8 -le 7) | Should -BeFalse
+    }
 }

diff --git a/tests/Test-RemoteMarker.Tests.ps1 b/tests/Test-RemoteMarker.Tests.ps1
index 3333333..4444444 100644
--- a/tests/Test-RemoteMarker.Tests.ps1
+++ b/tests/Test-RemoteMarker.Tests.ps1
@@ -1,3 +1,9 @@
 Describe 'Test-RemoteMarker' {
+    It 'passes MarkerPath as the remote argument' {
+        Mock Invoke-Command { $true } -ParameterFilter { $ComputerName -eq 'host1' -and $ArgumentList[0] -eq 'C:\IR\ready.flag' }
+        Test-RemoteMarker -ComputerName host1 -MarkerPath 'C:\IR\ready.flag' | Should -BeTrue
+        Assert-MockCalled Invoke-Command -Times 1 -ParameterFilter { $ArgumentList[0] -eq 'C:\IR\ready.flag' }
+    }
 }
